package io.github.sylirre.terminal.ui;

import android.app.Activity;
import android.content.Context;
import android.graphics.Color;
import android.os.Build;
import android.util.TypedValue;
import android.view.View;
import android.view.WindowInsetsController;

import io.github.sylirre.terminal.R;

/**
 * The whole-app theme. The selected {@link TerminalTheme} ({@link ThemeStore})
 * colors the terminal and, through the Palette.* style of the same name
 * (res/values/palettes.xml, generated by scripts/gen-app-palettes.py), every
 * other surface: each Activity calls {@link #apply} before inflating, so its
 * layouts, drawables, dialogs and {@link Chrome#color} lookups resolve the
 * palette's theme attrs. A user theme borrows the palette of the preset whose
 * background is closest to its own.
 */
final class AppTheme {

    private AppTheme() {}

    /** Overlays the selected theme's palette on {@code a} and matches the system-bar icons to it. */
    static void apply(Activity a) {
        a.getTheme().applyStyle(style(a), true);
        setLightSystemBars(a, isLight(a));
    }

    /** The Palette.* style for the selected theme. */
    static int style(Context c) {
        TerminalTheme t = new ThemeStore(c).current();
        int s = presetStyle(t.name);
        return s != 0 ? s : presetStyle(nearestPreset(t.background).name);
    }

    /** True when the applied palette is a light one (dark ink on light surfaces). */
    static boolean isLight(Context c) {
        TypedValue v = new TypedValue();
        return c.getTheme().resolveAttribute(R.attr.palette_light, v, true)
                && v.type == TypedValue.TYPE_INT_BOOLEAN && v.data != 0;
    }

    /** Dark status/nav-bar icons (for a light surface behind them) or light ones. */
    static void setLightSystemBars(Activity a, boolean light) {
        View decor = a.getWindow().getDecorView();
        if (Build.VERSION.SDK_INT >= 30) {
            WindowInsetsController controller = decor.getWindowInsetsController();
            if (controller != null) {
                int mask = WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS
                        | WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS;
                controller.setSystemBarsAppearance(light ? mask : 0, mask);
            }
        } else {
            int flags = View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR
                    | View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;
            int vis = decor.getSystemUiVisibility();
            decor.setSystemUiVisibility(light ? vis | flags : vis & ~flags);
        }
    }

    private static int presetStyle(String name) {
        switch (name) {
            case "Solarized Dark": return R.style.Palette_SolarizedDark;
            case "Solarized Light": return R.style.Palette_SolarizedLight;
            case "Tokyo Night": return R.style.Palette_TokyoNight;
            case "Catppuccin Mocha": return R.style.Palette_CatppuccinMocha;
            case "Rosé Pine": return R.style.Palette_RosePine;
            case "Kanagawa": return R.style.Palette_Kanagawa;
            case "Everforest": return R.style.Palette_Everforest;
            case "Gruvbox Dark": return R.style.Palette_GruvboxDark;
            case "Nord": return R.style.Palette_Nord;
            case "Dracula": return R.style.Palette_Dracula;
            case "One Dark": return R.style.Palette_OneDark;
            case "Classic": return R.style.Palette_Classic;
            default: return 0;
        }
    }

    private static TerminalTheme nearestPreset(int bg) {
        TerminalTheme best = ThemePresets.DEFAULT;
        long bestD = Long.MAX_VALUE;
        for (TerminalTheme t : ThemePresets.ALL) {
            long dr = Color.red(t.background) - Color.red(bg);
            long dg = Color.green(t.background) - Color.green(bg);
            long db = Color.blue(t.background) - Color.blue(bg);
            long d = dr * dr + dg * dg + db * db;
            if (d < bestD) {
                bestD = d;
                best = t;
            }
        }
        return best;
    }
}
